create or replace function public.get_public_properties(p_organization_slug text,p_purpose text default null,p_featured_only boolean default false,p_limit integer default 24) returns setof public.properties language sql stable security definer set search_path=public as $$ select p from public.properties p join public.organizations o on o.id=p.organization_id where o.slug=lower(trim(p_organization_slug)) and o.status in ('trial','active') and p.status='published' and p.deleted_at is null and (p_purpose is null or (p_purpose='sale' and p.purpose in ('sale','sale_and_rent')) or (p_purpose='rent' and p.purpose in ('rent','sale_and_rent'))) and (not p_featured_only or p.featured=true) order by p.created_at desc limit greatest(1,least(coalesce(p_limit,24),100)) $$; revoke all on function public.get_public_properties(text,text,boolean,integer) from public; grant execute on function public.get_public_properties(text,text,boolean,integer) to anon,authenticated; create or replace function public.get_public_property_by_slug(p_organization_slug text,p_property_slug text) returns public.properties language sql stable security definer set search_path=public as $$ select p from public.properties p join public.organizations o on o.id=p.organization_id where o.slug=lower(trim(p_organization_slug)) and o.status in ('trial','active') and p.slug=p_property_slug and p.status='published' and p.deleted_at is null limit 1 $$; revoke all on function public.get_public_property_by_slug(text,text) from public; grant execute on function public.get_public_property_by_slug(text,text) to anon,authenticated;